body.script:
const ASSET_CDN =
  "https://cdn.jsdelivr.net/gh/purpleskulltrooper85-svg/Deltarune-Web@main";

const CHAPTER_NAMES = [
  "The Beginning",
  "A Cyber's World",
  "Late Night",
  "Prophecy",
  "Festival Day"
];

const menuScreen = document.getElementById("menu-screen");
const menu = document.getElementById("menu");
const transition = document.getElementById("transition");
const gameScreen = document.getElementById("game-screen");
const gameFrame = document.getElementById("game-frame");
const gameLoading = document.getElementById("game-loading");
const loadingFill = document.getElementById("loading-bar-fill");
const backButton = document.getElementById("back-button");

const backgroundAudio = document.getElementById("background-audio");
const moveAudio = document.getElementById("move-audio");
const selectAudio = document.getElementById("select-audio");

let selectedIndex = 0;
let musicStarted = false;
let chapterIsLoading = false;
let loadingInterval = null;
let loadingProgress = 0;

function asset(path) {
  return `${ASSET_CDN}/${path
    .split("/")
    .map(part => encodeURIComponent(part))
    .join("/")}`;
}

function chapterHTMLURL(chapterNumber) {
  return asset(`chapter${chapterNumber}/index.html`);
}

function chapterBaseURL(chapterNumber) {
  return `${ASSET_CDN}/chapter${chapterNumber}/`;
}

function playSound(audio) {
  audio.pause();
  audio.currentTime = 0;
  audio.play().catch(() => {});
}

function startBackgroundAudio() {
  if (musicStarted) return;

  backgroundAudio.volume = 0.38;

  backgroundAudio.play()
    .then(() => {
      musicStarted = true;
    })
    .catch(() => {});
}

function menuImage(className, path, alt, fallbackClass, fallbackText) {
  return `
    <img
      class="${className}"
      src="${asset(path)}"
      alt="${alt}"
      onerror="this.classList.add('failed')"
    />
    <span class="${fallbackClass}">${fallbackText}</span>
  `;
}

function buildMenu() {
  let html = "";

  for (let chapterNumber = 1; chapterNumber <= 5; chapterNumber++) {
    html += `
      <button
        class="chapter"
        type="button"
        data-chapter="${chapterNumber}"
        aria-label="Start Chapter ${chapterNumber}"
      >
        <img
          class="heart"
          src="${asset("assets/undertale-icon.png")}"
          alt=""
          onerror="this.style.display='none'"
        />

        ${menuImage(
          "chapter-text",
          `assets/chapter-text/chapter-${chapterNumber}.png`,
          `Chapter ${chapterNumber}`,
          "fallback-text",
          `Chapter ${chapterNumber}`
        )}

        ${menuImage(
          "chapter-name",
          `assets/chapter-text/chapter-name-${chapterNumber}.png`,
          CHAPTER_NAMES[chapterNumber - 1],
          "fallback-name",
          CHAPTER_NAMES[chapterNumber - 1]
        )}

        <span class="icon-holder">
          <img
            class="chapter-icon"
            src="${asset(`assets/Deltarune Icons/Chapter ${chapterNumber}.png`)}"
            alt=""
            onerror="this.style.display='none'"
          />
        </span>
      </button>
    `;
  }

  html += `
    <button class="chapter locked" type="button" disabled="disabled">
      <span class="locked-label">Chapter 6</span>
      <span class="locked-name">--</span>
      <span class="icon-holder"></span>
    </button>

    <button class="chapter locked" type="button" disabled="disabled">
      <span class="locked-label">Chapter 7</span>
      <span class="locked-name">--</span>
      <span class="icon-holder"></span>
    </button>

    <footer id="menu-footer">
      <div class="copyright">
        (C) Toby Fox 2018–2026<br />
        DELTARUNE
      </div>

      <button id="quit-button" type="button">Quit</button>

      <div class="dots" aria-hidden="true">⠿</div>
    </footer>
  `;

  menu.innerHTML = html;
}

function chapters() {
  return [...document.querySelectorAll(".chapter:not(.locked)")];
}

function selectChapter(index, playMove = true) {
  const allChapters = chapters();
  const nextIndex =
    (index + allChapters.length) % allChapters.length;

  const changed = nextIndex !== selectedIndex;

  selectedIndex = nextIndex;

  allChapters.forEach((chapter, i) => {
    chapter.classList.toggle("selected", i === selectedIndex);
  });

  if (changed && playMove) {
    startBackgroundAudio();
    playSound(moveAudio);
  }
}

function setProgress(value) {
  loadingProgress = Math.max(0, Math.min(100, value));
  loadingFill.style.width = `${loadingProgress}%`;
}

function startLoadingBar() {
  clearInterval(loadingInterval);
  setProgress(0);
  loadingFill.style.background = "#fff";

  loadingInterval = setInterval(() => {
    if (loadingProgress < 88) {
      setProgress(
        loadingProgress + (loadingProgress < 45 ? 5 : 1.8)
      );
    }
  }, 120);
}

function finishLoadingBar() {
  clearInterval(loadingInterval);
  setProgress(100);

  setTimeout(() => {
    gameLoading.style.display = "none";
  }, 180);
}

function resetLoadingBar() {
  clearInterval(loadingInterval);
  setProgress(0);
  loadingFill.style.background = "#fff";
}

function addChapterBase(html, chapterNumber) {
  const baseTag =
    `<base href="${chapterBaseURL(chapterNumber)}" />`;

  if (/<base\b[^>]*>/i.test(html)) {
    return html.replace(/<base\b[^>]*>/i, baseTag);
  }

  if (/<head\b[^>]*>/i.test(html)) {
    return html.replace(
      /<head\b[^>]*>/i,
      match => `${match}\n${baseTag}\n`
    );
  }

  return `${baseTag}\n${html}`;
}

async function loadChapterFromCDN(chapterNumber) {
  try {
    const response = await fetch(chapterHTMLURL(chapterNumber), {
      mode: "cors",
      cache: "no-store"
    });

    if (!response.ok) {
      throw new Error(
        `Failed to load Chapter ${chapterNumber}: ${response.status}`
      );
    }

    const originalHTML = await response.text();
    const chapterHTML = addChapterBase(
      originalHTML,
      chapterNumber
    );

    const gameDocument = gameFrame.contentWindow.document;

    gameDocument.open();
    gameDocument.write(chapterHTML);
    gameDocument.close();
  } catch (error) {
    console.error(error);

    clearInterval(loadingInterval);
    setProgress(100);
    loadingFill.style.background = "#ff0000";
  }
}

function launchChapter(chapterNumber) {
  if (chapterIsLoading) return;

  chapterIsLoading = true;

  startBackgroundAudio();
  playSound(selectAudio);
  backgroundAudio.pause();

  menuScreen.classList.add("chapter-leaving");
  transition.classList.add("play");

  setTimeout(() => {
    gameScreen.style.display = "block";
    backButton.style.display = "block";
    gameLoading.style.display = "grid";

    startLoadingBar();
    loadChapterFromCDN(chapterNumber);
  }, 760);
}

gameFrame.addEventListener("load", () => {
  finishLoadingBar();
});

function returnToMenu() {
  playSound(selectAudio);

  gameFrame.src = "about:blank";

  gameScreen.style.display = "none";
  backButton.style.display = "none";
  gameLoading.style.display = "grid";

  transition.classList.remove("play");
  menuScreen.classList.remove("chapter-leaving");

  menu.style.animation = "none";
  menu.style.transform = "";
  menu.style.opacity = "";

  void menu.offsetWidth;

  menu.style.animation = "";

  chapterIsLoading = false;

  resetLoadingBar();

  backgroundAudio.play()
    .then(() => {
      musicStarted = true;
    })
    .catch(() => {});
}

function setupEvents() {
  const allChapters = chapters();

  allChapters.forEach((chapter, index) => {
    chapter.addEventListener("mouseenter", () => {
      selectChapter(index, true);
    });

    chapter.addEventListener("focus", () => {
      selectChapter(index, true);
    });

    chapter.addEventListener("click", () => {
      startBackgroundAudio();
      selectChapter(index, false);
      launchChapter(Number(chapter.dataset.chapter));
    });
  });

  document.addEventListener("pointerdown", startBackgroundAudio, {
    once: true
  });

  document.addEventListener("keydown", event => {
    if (gameScreen.style.display === "block") {
      if (event.key === "Escape") {
        returnToMenu();
      }

      return;
    }

    startBackgroundAudio();

    if (
      event.key === "ArrowDown" ||
      event.key.toLowerCase() === "s"
    ) {
      event.preventDefault();
      selectChapter(selectedIndex + 1, true);
      chapters()[selectedIndex].focus();
    }

    if (
      event.key === "ArrowUp" ||
      event.key.toLowerCase() === "w"
    ) {
      event.preventDefault();
      selectChapter(selectedIndex - 1, true);
      chapters()[selectedIndex].focus();
    }

    if (event.key === "Enter" || event.key === " ") {
      const focused =
        document.activeElement.closest?.(".chapter");

      if (focused && !focused.classList.contains("locked")) {
        event.preventDefault();
        launchChapter(Number(focused.dataset.chapter));
      }
    }
  });

  document
    .getElementById("quit-button")
    .addEventListener("click", () => {
      playSound(selectAudio);
      window.close();
    });

  backButton.addEventListener("click", returnToMenu);
}

buildMenu();
setupEvents();
selectChapter(0, false);
